/*
 * ldp.c -- TASK/SDK01 package J runtime probe: `long double' (IEEE binary128)
 * in libc and libm, run on NewTOS (QEMU raspi4b, C:\AUTO\LDP.NCP, console,
 * before the AES). Built with `sdk/bin/newtos-cc -lm` (build-probe.sh): the
 * SHIPPED archives, i.e. the machine code that also uses x18 (the kernel
 * preserves it); the host test ran the -ffixed-x18 rebuild of the same
 * members.
 *
 * Expected values: expected.h, generated by expected.py from the host test's
 * oracle (exact rational arithmetic) -- exact values for printf/strtold/
 * sscanf/qecvt/qfcvt/qgcvt/scalbln(f,l)/fenv; for expl/logl/sinl/powl/cbrtl the bit pattern
 * the host run of the same code gives (expected.txt has their ulp distance to
 * a 130-digit reference).
 *
 *   P  snprintf %.35Le %La %Lf %Lg %.40Lf of binary128 values, LDBL_MAX and
 *      the smallest subnormal; double %f of INFINITY/NAN (the float word order
 *      fix in include/bits/endian.h)
 *   S  strtold (0.1, a subnormal, LDBL_MAX), sscanf("%Lf") of pi to 36 digits
 *   Q  qecvt(1/3,10), qfcvt(2.5,3) (static buffer + atexit path), qgcvt(0.125,6)
 *      -- SDK01 E printed "-0.000000000", "", "0"
 *   F  fesetround(FE_UPWARD/DOWNWARD) + a binary128 addition, <fenv.h> included
 *      through newtos-cc -lm without the -I .../src workaround of SDK01 E;
 *      1/3 under FE_UPWARD as INFO (compiler-rt's __divtf3 ignores the mode)
 *   M  scalbln, scalblnf, scalblnl (did not link before), scalbnl to the
 *      smallest subnormal, expl(1), logl(2), sinl(1), powl(2, .5), cbrtl(2),
 *      sqrtl(2.25), isinf/isnan/isfinite on long double
 *
 * Every check prints "[LDP] ok|FAIL ..."; ends with "LDP RESULT fails=<n>".
 */
#include <fenv.h>
#include <float.h>
#include <limits.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <mint/osbind.h>
#include "expected.h"

typedef unsigned long long u64;
extern char *qecvt(long double, int, int *, int *);
extern char *qfcvt(long double, int, int *, int *);
extern char *qgcvt(long double, int, char *);

static int fails, oks;

static void hex64(u64 v)
{
	static const char d[] = "0123456789abcdef";
	char b[17];
	for (int i = 0; i < 16; i++) b[i] = d[(v >> ((15 - i) * 4)) & 0xf];
	b[16] = 0;
	Cconws(b);
}
static void num(long v)
{
	char b[24]; int i = 23; int neg = v < 0; unsigned long u = neg ? -(unsigned long)v : (unsigned long)v;
	b[i] = 0;
	do { b[--i] = (char)('0' + u % 10); u /= 10; } while (u);
	if (neg) b[--i] = '-';
	Cconws(b + i);
}
static void res(int ok, const char *what)
{
	Cconws(ok ? "[LDP] ok   " : "[LDP] FAIL ");
	Cconws(what);
	if (ok) oks++; else fails++;
}
static void checks(const char *what, const char *got, const char *want)
{
	int ok = strcmp(got, want) == 0;
	res(ok, what); Cconws(" = \""); Cconws(got); Cconws("\"");
	if (!ok) { Cconws(" want \""); Cconws(want); Cconws("\""); }
	Cconws("\r\n");
}
static void checkld(const char *what, long double x, u64 hi, u64 lo)
{
	u64 w[2];
	memcpy(w, &x, 16);
	int ok = w[1] == hi && w[0] == lo;
	res(ok, what); Cconws(" = "); hex64(w[1]); Cconws(":"); hex64(w[0]);
	if (!ok) { Cconws(" want "); hex64(hi); Cconws(":"); hex64(lo); }
	Cconws("\r\n");
}
static void checki(const char *what, long got, long want)
{
	res(got == want, what); Cconws(" = "); num(got);
	if (got != want) { Cconws(" want "); num(want); }
	Cconws("\r\n");
}
static long double ld(u64 hi, u64 lo)
{
	u64 w[2] = { lo, hi };
	long double x;
	memcpy(&x, w, 16);
	return x;
}

int main(void)
{
	char b[256];
	volatile long double third = 1.0L / 3.0L, two3 = 2.0L / 3.0L, big = 1e4000L;
	volatile long double maxl = LDBL_MAX, dmin = ld(0, 1);

	Cconws("[LDP] SDK01 J long double probe\r\n");
	/* P */
	snprintf(b, sizeof b, "%.35Le", third);  checks("P %.35Le 1/3", b, E_P35E_THIRD);
	snprintf(b, sizeof b, "%La", third);     checks("P %La 1/3", b, E_PLA_THIRD);
	snprintf(b, sizeof b, "%Lf", third);     checks("P %Lf 1/3", b, E_PLF_THIRD);
	snprintf(b, sizeof b, "%Lg", big);       checks("P %Lg 1e4000L", b, E_PLG_1E4000);
	snprintf(b, sizeof b, "%.20Le", maxl);   checks("P %.20Le LDBL_MAX", b, E_P20E_MAX);
	snprintf(b, sizeof b, "%.20Le", dmin);   checks("P %.20Le denorm_min", b, E_P20E_DMIN);
	snprintf(b, sizeof b, "%La", dmin);      checks("P %La denorm_min", b, E_PLA_DMIN);
	snprintf(b, sizeof b, "%.40Lf", two3);   checks("P %.40Lf 2/3", b, E_P40F_TWO3);
	snprintf(b, sizeof b, "%Lf", -0.0L);     checks("P %Lf -0.0L", b, "-0.000000");
	snprintf(b, sizeof b, "%Lf %Lf", (long double)INFINITY, -(long double)INFINITY);
	checks("P %Lf +-inf", b, "inf -inf");
	snprintf(b, sizeof b, "%f %f %e", (double)INFINITY, -(double)INFINITY, (double)NAN);
	checks("P double %f inf, %e nan", b, "inf -inf nan");
	/* S */
	char *end;
	checkld("S strtold 0.1", strtold("0.1", &end), E_STRTOLD_01);
	checkld("S strtold 1e-4950", strtold("1e-4950", &end), E_STRTOLD_SUB);
	checkld("S strtold LDBL_MAX", strtold("1.18973149535723176508575932662800702e4932", &end), E_STRTOLD_MAX);
	long double pi = 0;
	int n = sscanf("x 3.14159265358979323846264338327950288", "x %Lf", &pi);
	checki("S sscanf %Lf count", n, 1);
	checkld("S sscanf %Lf pi", pi, E_SSCANF_PI);
	/* Q */
	int dp = -99, sg = -99;
	char *r = qecvt(third, 10, &dp, &sg);
	checks("Q qecvt(1/3,10)", r, E_QECVT); checki("Q qecvt decpt", dp, 0); checki("Q qecvt sign", sg, 0);
	r = qfcvt(2.5L, 3, &dp, &sg);
	checks("Q qfcvt(2.5,3)", r, E_QFCVT); checki("Q qfcvt decpt", dp, 1);
	r = qgcvt(0.125L, 6, b);
	checks("Q qgcvt(0.125,6)", r, E_QGCVT);
	/* F -- compiler-rt's soft-float honours the FPCR rounding mode in
	   __addtf3/__subtf3 only (fp_add_impl.inc is the only user of
	   __fe_getround); __divtf3/__multf3 always round to nearest. So the
	   mode is checked with an addition, and 1/3 under FE_UPWARD is INFO. */
	volatile long double one = 1.0L, three = 3.0L, tiny = 0x1p-200L;
	checki("F fesetround(FE_UPWARD)", fesetround(FE_UPWARD), 0);
	long double up = one + tiny, q_up = one / three;
	checki("F fegetround", fegetround(), FE_UPWARD);
	fesetround(FE_DOWNWARD);
	long double dn = one - tiny;
	fesetround(FE_TONEAREST);
	long double ne = one + tiny;
	checkld("F FE_UPWARD 1+2^-200", up, 0x3fff000000000000ULL, 1);
	checkld("F FE_DOWNWARD 1-2^-200", dn, 0x3ffeffffffffffffULL, 0xffffffffffffffffULL);
	checkld("F FE_TONEAREST 1+2^-200", ne, 0x3fff000000000000ULL, 0);
	checkld("F 1/3 nearest", one / three, E_THIRD);
	{
		u64 w[2];
		memcpy(w, &q_up, 16);
		Cconws("[LDP] INFO 1/3 under FE_UPWARD (__divtf3 rounds to nearest) = ");
		hex64(w[1]); Cconws(":"); hex64(w[0]); Cconws("\r\n");
	}
	/* M */
	volatile long nbig = 1L << 40;
	double dd = scalbln(1.0, nbig);
	checki("M scalbln(1, 2^40) isinf", isinf(dd) != 0, 1);
	float ff = scalblnf(1.0f, -nbig);
	checki("M scalblnf(1, -2^40) == 0", ff == 0.0f, 1);
	long double l = scalblnl(1.0L, nbig);
	checki("M scalblnl(1, 2^40) isinf", isinf(l) != 0, 1);
	checkld("M scalbnl(1, -16494)", scalbnl(1.0L, -16494), 0, 1);
	checkld("M expl(1)", expl(one), E_EXPL1);
	checkld("M logl(2)", logl(2.0L * one), E_LOGL2);
	checkld("M sinl(1)", sinl(one), E_SINL1);
	checkld("M powl(2, .5)", powl(2.0L * one, 0.5L * one), E_POWL);
	checkld("M cbrtl(2)", cbrtl(2.0L * one), E_CBRTL2);
	checkld("M sqrtl(2.25)", sqrtl(2.25L * one), 0x3fff800000000000ULL, 0);
	volatile long double linf = INFINITY, lnan = NAN;
	checki("M isinf(-inf L)", isinf(-linf) != 0, 1);
	checki("M isnan(nan L)", isnan(lnan) != 0, 1);
	checki("M isfinite(inf L)", isfinite(linf) != 0, 0);
	checki("M isfinite(max L)", isfinite(maxl) != 0, 1);

	Cconws("LDP RESULT fails="); num(fails); Cconws(" ok="); num(oks); Cconws("\r\n");
	return fails != 0;
}
